          "directory_entry_name": "衛武營國家藝術文化中心",
          "account": "https://www.youtube.com/channel/UCinakIiUgs09kXaXI0mwo-A",
          "platform": "youtube",
          "platform_label": "YouTube",
          "posted_at": "2026-09-15T03:24:52+00:00",
          "posted_at_local": "2026-09-15 11:24",
          "like_count": null,
          "comment_count": null,
          "share_count": null,
